from collections import deque

def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str):
        return None
    if not path.startswith('/'):
        if cwd == '/':
            path = '/' + path
        else:
            path = cwd + '/' + path

    components = deque(path.split('/'))
    current = '/'
    link_count = 0

    while components:
        comp = components.popleft()
        if comp == '' or comp == '.':
            continue
        if comp == '..':
            if current != '/':
                idx = current.rfind('/')
                if idx <= 0:
                    current = '/'
                else:
                    current = current[:idx]
            continue

        # build the candidate new path
        if current == '/':
            new_path = '/' + comp
        else:
            new_path = current + '/' + comp

        if new_path in links:
            link_count += 1
            if link_count > 8:
                return None
            target = links[new_path]
            if not isinstance(target, str):
                return None
            if target.startswith('/'):
                target_path = target
            else:
                if current == '/':
                    target_path = '/' + target
                else:
                    target_path = current + '/' + target
            target_comps = deque(target_path.split('/'))
            # prepend target's components to the remaining ones
            components = target_comps + components
        else:
            current = new_path

    if current == '':
        current = '/'

    return current

